class Solution:
    def minArrivalsToDiscard(self, arrivals, w, m):
        n = len(arrivals)
        kept = [False] * n
        discards = 0
        for i in range(n):
            c = 0
            for j in range(max(0, i - w + 1), i):
                if kept[j] and arrivals[j] == arrivals[i]:
                    c += 1
            if c >= m:
                discards += 1
            else:
                kept[i] = True
        return discards

