from collections import defaultdict
class Solution:
    def minArrivalsToDiscard(self, arrivals, w, m):
        cnt = defaultdict(int)
        kept = [False] * len(arrivals)
        discards = 0
        for i, a in enumerate(arrivals):
            if cnt[a] == m:
                discards += 1
            else:
                cnt[a] += 1
                kept[i] = True
            j = i - w + 1
            if j >= 0 and kept[j]:
                cnt[arrivals[j]] -= 1
        return discards

