class Solution {
    public int minArrivalsToDiscard(int[] arrivals, int w, int m) {
        Map<Integer, Integer> cnt = new HashMap<>();
        int n = arrivals.length, discards = 0;
        boolean[] kept = new boolean[n];
        for (int i = 0; i < n; i++) {
            int a = arrivals[i];
            int c = cnt.getOrDefault(a, 0);
            if (c == m) discards++;
            else { cnt.put(a, c + 1); kept[i] = true; }
            int j = i - w + 1;
            if (j >= 0 && kept[j]) cnt.merge(arrivals[j], -1, Integer::sum);
        }
        return discards;
    }
}

