var minArrivalsToDiscard = function(arrivals, w, m) {
    const cnt = new Map();
    const kept = new Array(arrivals.length).fill(false);
    let discards = 0;
    for (let i = 0; i < arrivals.length; i++) {
        const a = arrivals[i];
        const c = cnt.get(a) || 0;
        if (c === m) discards++;
        else { cnt.set(a, c + 1); kept[i] = true; }
        const j = i - w + 1;
        if (j >= 0 && kept[j]) cnt.set(arrivals[j], cnt.get(arrivals[j]) - 1);
    }
    return discards;
};
